import Image from "next/image";
import { Surface } from "@/components/ui/Surface";
import type { CaseStudy } from "@/content/types";
import { cn, known } from "@/lib/utils";

/**
 * A case study on a floating glass device. Uses the screenshot when one exists
 * (public/work/<slug>.webp, generated by scripts/screenshot-sites.mjs) and a
 * branded gradient poster until then.
 */
export function DeviceCard({ study, className }: { study: CaseStudy; className?: string }) {
  const [a, b] = study.accent;
  return (
    <Surface specular interactive className={cn("flex h-full flex-col overflow-hidden p-3", className)}>
      <div
        className="relative aspect-[16/10] w-full overflow-hidden rounded-[18px] border border-border"
        style={{ background: `linear-gradient(135deg, ${a}, ${b})` }}
      >
        {study.image ? (
          <Image
            src={study.image}
            alt={`${study.client} screenshot`}
            fill
            sizes="(min-width: 1024px) 520px, 84vw"
            className="object-cover object-top"
          />
        ) : (
          <div className="absolute inset-0 grid place-items-center p-6 text-center">
            <div>
              <p className="t-h3 text-background">{study.client}</p>
              <p className="t-small mt-1 text-background/80">{study.industry}</p>
            </div>
          </div>
        )}
        <div className="absolute inset-x-0 top-0 flex items-center gap-1.5 bg-background/25 px-3 py-2">
          <span className="size-2 rounded-full bg-background/60" />
          <span className="size-2 rounded-full bg-background/60" />
          <span className="size-2 rounded-full bg-background/60" />
          <span className="t-small ml-2 truncate text-background/80">
            {study.liveUrl?.replace(/^https?:\/\//, "") ?? study.client}
          </span>
        </div>
      </div>
      <div className="flex flex-1 flex-col px-3 pb-3 pt-4">
        <div className="flex items-center justify-between gap-3">
          <p className="t-eyebrow">{study.industry}</p>
          {known(study.location) ? <p className="t-small text-fg-3">{study.location}</p> : null}
        </div>
        <h3 className="t-h4 mt-2">{study.title}</h3>
        <p className="t-small mt-2 line-clamp-2 text-fg-2">{study.summary}</p>
        <ul className="mt-auto flex flex-wrap gap-1.5 pt-4">
          {study.stack.slice(0, 4).map((s) => (
            <li key={s} className="chip">
              {s}
            </li>
          ))}
        </ul>
      </div>
    </Surface>
  );
}
